/*
 * Embeds the real source files of the demo pages so the page can show them next to the live result.
 * What is displayed is exactly what compiles, never a hand-written copy.
 *
 * Output: projects/demo/src/app/generated/sources.ts (git-ignored, regenerated by `npm run snippets`).
 * Key = path relative to projects/demo/src/app, with forward slashes.
 */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..', 'projects', 'demo', 'src', 'app');
const out = path.join(root, 'generated', 'sources.ts');
const SKIP = new Set(['generated', 'data']);

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) return SKIP.has(e.name) ? [] : walk(p);
    return /\.(ts|html|scss)$/.test(e.name) ? [p] : [];
  });
}

const sources = {};
for (const file of walk(root)) {
  const key = path.relative(root, file).split(path.sep).join('/');
  sources[key] = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n').trimEnd();
}

fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, `// Generated by scripts/embed-snippets.cjs - do not edit.\nexport const SOURCES: Record<string, string> = ${JSON.stringify(sources, null, 2)};\n`);
console.log(`sources: ${Object.keys(sources).length} files embedded in ${path.relative(process.cwd(), out)}`);
